      const captainOnCourtField = team === 'home' ? 'homeCourtCaptain' : 'awayCourtCaptain'
      const currentCourtCaptain = data?.match?.[captainOnCourtField]
      const isLeavingCourtCaptain = String(currentCourtCaptain) === String(playerOut)

