                                  padding: '0.5cqh 1.5cqh',
                                  borderRadius: '2cqh',
                                  background: player.isLfp ? 'rgba(249, 115, 22, 0.9)' : 'rgba(147, 51, 234, 0.9)',
                                  color: '#fff',
                                  lineHeight: 1,
